    "imageCredit": "Imagen ilustrativa. Unsplash.",
    "sources": [
      "https://www.indec.gob.ar/uploads/informesdeprensa/canasta_crianza_11_26F9D722BE15.pdf",
      "https://www.indec.gob.ar/indec/Portada"
    ]
